) {
    val hasFundamentals = detail?.fundamentals != null
    val hasMacro = detail?.macro != null
    val hasTabContent = hasFundamentals || hasMacro

    DetailTabContent(hasTabContent, lazyListState, contentPadding, sectionSpacing) {
