@Composable
private fun ThesisTabContent(
    detail: StockDetail?,
    preview: StockPreview?,
    expandedChipIds: Set<String>,
    onToggleChip: (String) -> Unit,
    lazyListState: LazyListState,
    contentPadding: PaddingValues,
    sectionSpacing: Dp
) {
    val thesis = detail?.executiveThesis
    val hasDeepStudy = thesis != null &&
        (thesis.whatTheNumbersSay != null || thesis.valuationContext != null || thesis.macroTransmissionVector != null)
    val hasScenario = detail?.scenarios.orEmpty().any { it.direction?.uppercase() == "BULLISH" || it.direction?.uppercase() == "BEARISH" }
    val hasConsider = !detail?.considerations.isNullOrEmpty()
    val hasSignalConditions = !detail?.conditionLabels.isNullOrEmpty()
    val hasNotCovered = detail?.notCovered != null
    val hasTabContent = hasDeepStudy || hasScenario || hasConsider || hasSignalConditions || hasNotCovered

    DetailTabContent(hasTabContent, lazyListState, contentPadding, sectionSpacing) {
        if (hasDeepStudy) {
            item { DeepStudy(thesis = thesis) }
        }
        if (hasScenario) {
            item { Scenarios(scenarios = detail?.scenarios) }
        }
        if (hasConsider) {
            item { Consider(considerations = detail?.considerations) }
        }
        if (hasSignalConditions) {
            item {
                SignalConditions(
                    conditionLabels = detail?.conditionLabels,
                    chipsAdded = preview?.chipsAdded.orEmpty(),
                    chipsRemoved = preview?.chipsRemoved.orEmpty(),
                    expandedChipIds = expandedChipIds,
                    onToggleChip = onToggleChip
                )
            }
        }
        if (hasNotCovered) {
            item { NotCoveredFooter(notCovered = detail?.notCovered) }
        }
    }
}

@Composable
private fun TimelineTabContent(
    detail: StockDetail?,
    lazyListState: LazyListState,
    contentPadding: PaddingValues,
    sectionSpacing: Dp
) {
    val hasForwardCalls = !detail?.calls?.open.isNullOrEmpty()
    val contextVault = detail?.contextVault
    val hasEventLog = contextVault != null && (!contextVault.eventLog.isNullOrEmpty() || contextVault.thirtyDayTrendTimeline != null)
    val hasTabContent = hasForwardCalls || hasEventLog

    DetailTabContent(hasTabContent, lazyListState, contentPadding, sectionSpacing) {
        if (hasForwardCalls) {
            item { ForwardCalls(calls = detail?.calls) }
        }
        if (hasEventLog) {
            item { EventLog(contextVault = contextVault) }
        }
    }
}

@Composable
private fun NewsTabContent(
    detail: StockDetail?,
    expandedNewsIds: Set<String>,
    onToggleNews: (String) -> Unit,
    onArticleClick: (String) -> Unit,
    lazyListState: LazyListState,
    contentPadding: PaddingValues,
    sectionSpacing: Dp
) {
    // Newest first -- `sourceDate` is the same `yyyy-MM-dd` shape every other date field on this
    // screen is, so it sorts correctly as a plain string without needing to parse it into a real
    // Date first.
    val sortedNews = detail?.topNewsStream.orEmpty().sortedByDescending { it.sourceDate.orEmpty() }
    val hasTabContent = sortedNews.isNotEmpty()

    DetailTabContent(hasTabContent, lazyListState, contentPadding, sectionSpacing) {
        if (hasTabContent) {
            item {
                DirectNews(
                    newsStream = sortedNews,
                    expandedNewsIds = expandedNewsIds,
                    onToggleNews = onToggleNews,
                    onArticleClick = onArticleClick
                )
            }
        }
    }
}

/**
 * Shared shell every tab uses. `TechnicalRead` and the HIGH-urgency alert used to render as a
 * leading block here, duplicated identically into every tab's own list -- both moved 2026-09-05 to
 * chrome level (`StockDetailRoute`, alongside the Deep Dive banner, same collapse-then-stick
 * behavior) as a single shared instance instead, since they're general context, not per-tab
 * content. Falls back to a centered muted "Nothing yet" line when a tab truly has none of its own
 * sections -- the general context now lives above the tab row regardless, so an empty tab reads as
 * empty rather than silently falling back to showing only that shared context again.
 */
@Composable
private fun DetailTabContent(
    hasTabContent: Boolean,
    lazyListState: LazyListState,
    contentPadding: PaddingValues,
    sectionSpacing: Dp,
    content: LazyListScope.() -> Unit
) {
    if (!hasTabContent) {
        Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
            Text(
                text = stringResource(id = R.string.stock_detail_tab_nothing_yet),
                style = MaterialTheme.typography.bodyMedium,
                color = LocalPulseColors.current.onSurfaceMuted
            )
        }
        return
    }

    LazyColumn(
        state = lazyListState,
        modifier = Modifier.fillMaxSize(),
        contentPadding = contentPadding,
        verticalArrangement = Arrangement.spacedBy(sectionSpacing)
    ) {
        content()
    }
}
